pub fn shuffle(points: &mut Vec<Point>, generator: &mut DefaultPRNG) {
    let length = points.len() as i32;
    if length == 0 {
        return;
    }

    for i in (1..length).rev() {
        points.swap(i as usize, generator.random_int(i as u32) as usize);
    }
